-- Thread 1 members
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, x.id, 1, 'Ascension of Isaiah 9:27 — *I saw a certain One standing, whose glory surpassed that of all, and His glory was great and wonderful.* The Formed-Son in pre-incarnational standing-position before the Great-Glory — the same Formed-essence the transfiguration pulls back the servant-form-veil to reveal at Matt 17:2.'
  FROM cross_reference_threads t, cross_references x, _s154_xref_lookup sv, _s154_xref_lookup tv
 WHERE t.slug = 'the-formless-father-and-the-formed-son-witnessed-in-ascension-of-isaiah'
   AND sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 17 AND sv.verse_number = 2
   AND tv.edition_slug = 'ascension-isaiah' AND tv.book_slug = 'ascension-isaiah' AND tv.chapter_number = 9 AND tv.verse_number = 27
   AND x.source_verse_id = sv.verse_id AND x.target_verse_id = tv.verse_id AND x.source = 'manual'
