-- ---------------------------------------------------------------------
-- Verification block.
-- ---------------------------------------------------------------------
DO $verify$
DECLARE
  v_xref_inserted INT;
  v_thread_inserted INT;
  v_member_inserted INT;
BEGIN
  SELECT count(*) INTO v_xref_inserted FROM cross_references x
    JOIN _s154_xref_lookup sv ON sv.verse_id = x.source_verse_id
   WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 17
     AND x.tier_required = 'extras' AND x.source = 'manual';

  SELECT count(*) INTO v_thread_inserted FROM cross_reference_threads
   WHERE slug IN (
     'the-formless-father-and-the-formed-son-witnessed-in-ascension-of-isaiah',
     'the-son-of-adam-glorified-in-1-enoch-throne-vision-and-parables',
     'eliyahu-as-reproof-prophet-turning-the-heart-in-sirach-48',
     'the-faithless-and-perverse-generation-in-sirach-wisdom-of-solomon-and-2-esdras',
     'the-just-man-as-son-of-yahuah-condemned-and-vindicated-in-wisdom-of-solomon-2'
   );

  SELECT count(*) INTO v_member_inserted
    FROM cross_reference_thread_members m
    JOIN cross_reference_threads t ON t.id = m.thread_id
   WHERE t.slug IN (
     'the-formless-father-and-the-formed-son-witnessed-in-ascension-of-isaiah',
     'the-son-of-adam-glorified-in-1-enoch-throne-vision-and-parables',
     'eliyahu-as-reproof-prophet-turning-the-heart-in-sirach-48',
     'the-faithless-and-perverse-generation-in-sirach-wisdom-of-solomon-and-2-esdras',
     'the-just-man-as-son-of-yahuah-condemned-and-vindicated-in-wisdom-of-solomon-2'
   );

  RAISE NOTICE 'S154 Matt 17 verify: extras xrefs from canon/matthew/17 = %, threads = %, members = %',
    v_xref_inserted, v_thread_inserted, v_member_inserted;

  IF v_thread_inserted <> 5 THEN
    RAISE EXCEPTION 'Expected 5 threads inserted; got %', v_thread_inserted;
  END IF;
  IF v_xref_inserted < 21 THEN
    RAISE EXCEPTION 'Expected at least 21 Matt-17 extras xrefs; got %', v_xref_inserted;
  END IF;
  IF v_member_inserted < 21 THEN
    RAISE EXCEPTION 'Expected at least 21 thread members; got %', v_member_inserted;
  END IF;
END;
$verify$;

COMMIT;
